34	                    /*debug_axi=*/true, /*instr_trace=*/false,
35	                    /*backdoor_load=*/false,
36	                    /*wfi_cb=*/std::nullopt, std::nullopt);
37	
38	  std::thread sc_main_thread([&tb]() { tb.start(); });
39	
40	  DataTransfer wrap_write, wrap_read, wrap_expect;
41	  /* WRAP */
42	  wrap_write.addr = 0x0;
43	  wrap_write.cmd = DataTransfer::WRITE;
44	  wrap_write.data =
45	      DATA(0x81, 0x82, 0x83, 0x84, 0x71, 0x72, 0x73, 0x74, 0x91, 0x92, 0x93,
46	           0x94, 0x81, 0x82, 0x83, 0x84, 0xa1, 0xa2, 0xa3, 0xa4, 0x91, 0x92,
47	           0x93, 0x94, 0xb1, 0xb2, 0xb3, 0xb4, 0xa1, 0xa2, 0xa3, 0xa4);
48	  wrap_write.byte_enable = nullptr;
49	  wrap_write.length = 32;
50	  wrap_write.streaming_width = 32;
51	  wrap_write.ext.gen_attr.enabled = true;
52	  wrap_write.ext.gen_attr.wrap = true;
53	
54	  wrap_read.addr = 0x0;
55	  wrap_read.cmd = DataTransfer::READ;
56	  wrap_read.byte_enable = nullptr;
57	  wrap_read.length = 32;
58	  wrap_read.streaming_width = 32;
59	  wrap_read.ext.gen_attr.enabled = true;
60	  wrap_read.ext.gen_attr.wrap = true;
61	  auto wrap_transfer = std::vector<DataTransfer>({
62	      utils::Write(
63	          0,
64	          DATA(0xa6, 0xa7, 0xa8, 0xa9, 0xaa, 0xab, 0xac, 0xad, 0xa6, 0xa7, 0xa8,
65	               0xa9, 0xaa, 0xab, 0xac, 0xad, 0xa6, 0xa7, 0xa8, 0xa9, 0xaa, 0xab,
66	               0xac, 0xad, 0xa6, 0xa7, 0xa8, 0xa9, 0xaa, 0xab, 0xac, 0xad),
67	          32),
68	      wrap_write,
69	      wrap_read,
70	      utils::Expect(
71	          DATA(0xa1, 0xa2, 0xa3, 0xa4, 0x91, 0x92, 0x93, 0x94, 0xb1, 0xb2, 0xb3,
72	               0xb4, 0xa1, 0xa2, 0xa3, 0xa4, 0xa1, 0xa2, 0xa3, 0xa4, 0x91, 0x92,
73	               0x93, 0x94, 0xb1, 0xb2, 0xb3, 0xb4, 0xa1, 0xa2, 0xa3, 0xa4),
74	          32),
75	  });
76	
77	  tb.EnqueueTransactionSync(wrap_transfer);
78	
79	  uint32_t dummy_data = 0x1234abcd;
80	  DataTransfer write32;
81	  write32.addr = 0;
82	  write32.cmd = DataTransfer::WRITE;
83	  write32.data = reinterpret_cast<uint8_t*>(&dummy_data);
84	  write32.length = 4;
85	  write32.byte_enable = nullptr;
86	  write32.byte_enable_length = 0;
87	  write32.streaming_width = 4;
88	  write32.ext.gen_attr.enabled = true;
89	  write32.ext.gen_attr.burst_width = 4;
90	
91	  DataTransfer read32;
92	  read32.addr = 0;
93	  read32.cmd = DataTransfer::READ;
94	  read32.data = reinterpret_cast<uint8_t*>(&dummy_data);
95	  read32.length = 4;
96	  read32.byte_enable = nullptr;
97	  read32.byte_enable_length = 0;
98	  read32.streaming_width = 4;
99	  read32.ext.gen_attr.enabled = true;
100	  read32.ext.gen_attr.burst_width = 4;
101	
102	  std::vector<DataTransfer> narrow_transfers;
103	  narrow_transfers.push_back(write32);
104	  narrow_transfers.push_back(read32);
105	  narrow_transfers.push_back(
106	      utils::Expect(reinterpret_cast<uint8_t*>(&dummy_data), 4));
107	
108	  write32.addr = 4;
109	  read32.addr = 4;
110	  narrow_transfers.push_back(write32);
111	  narrow_transfers.push_back(read32);
112	  narrow_transfers.push_back(
113	      utils::Expect(reinterpret_cast<uint8_t*>(&dummy_data), 4));
114	
115	  write32.addr = 8;
116	  read32.addr = 8;
117	  narrow_transfers.push_back(write32);
118	  narrow_transfers.push_back(read32);
119	  narrow_transfers.push_back(
120	      utils::Expect(reinterpret_cast<uint8_t*>(&dummy_data), 4));
121	  tb.EnqueueTransactionSync(utils::merge(narrow_transfers));
122	
123	  sc_stop();
124	  sc_main_thread.join();
125	
126	  return 0;
